const $=s=>document.querySelector(s),KEY='la-tene-fieldgame-v7';
const totalTasks=stations.reduce((n,s)=>n+s.tasks.length,0);
function validKey(k){const parts=k.split('-');return parts.length===2&&parts.every(p=>/^\d+$/.test(p))&&!!stations[+parts[0]]?.tasks[+parts[1]];}
const autoCount=stations.flatMap(s=>s.tasks).filter(t=>!['write','dig'].includes(t.type)).length;
let state={station:0,task:0,results:{},answers:{},draft:''},storageOK=true,selection=[],order=[],activeCard=null,showResult=false;
try{const raw=localStorage.getItem(KEY);const saved=raw?JSON.parse(raw):null;if(saved&&typeof saved==='object'){state.station=Number.isInteger(saved.station)&&saved.station>=0&&saved.station<stations.length?saved.station:0;state.task=Number.isInteger(saved.task)&&saved.task>=0&&saved.task<3?saved.task:0;state.draft=typeof saved.draft==='string'?saved.draft:'';for(const [k,v]of Object.entries(saved.results||{}))if(validKey(k)&&typeof v?.correct==='boolean')state.results[k]={correct:v.correct,first:v.first===true};for(const [k,v]of Object.entries(saved.answers||{}))if(validKey(k)&&Array.isArray(v)&&v.every(x=>typeof x==='string'||typeof x==='number'||x===null))state.answers[k]=v;}else{const old=JSON.parse(localStorage.getItem('helvetier-neuchatel-v4'));if(typeof old?.draft==='string')state.draft=old.draft;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/ae/g,'a').replace(/oe/g,'o').replace(/ue/g,'u').replace(/[^a-z0-9]/g,'');}
const key=()=>`${state.station}-${state.task}`;
const currentStation=()=>stations[state.station];
const current=()=>currentStation().tasks[state.task];
function loadAnswer(){selection=[...(state.answers[key()]||[])];const n=current().items?.length||0;order=current().type==='order'&&selection.length===n&&new Set(selection).size===n&&selection.every(v=>Number.isInteger(v)&&v>=0&&v<n)?[...selection]:Array.from({length:n},(_,i)=>i);activeCard=null;}
function remember(){state.answers[key()]=current().type==='order'?[...order]:[...selection];save();}
function start(s,t=0){state.station=s;state.task=t;showResult=false;loadAnswer();save();render();$('#game').focus({preventScroll:true});$('#game').scrollIntoView({block:'start'});}
function sidebar(){const count=Object.values(state.results).filter(r=>r.correct).length,points=Object.values(state.results).filter(r=>r.first).length;
 $('#stations').innerHTML=stations.map((s,i)=>{const done=s.tasks.every((_,j)=>state.results[`${i}-${j}`]?.correct);return `<button class="station ${i===state.station&&!showResult?'active':''} ${done?'done':''}" data-station="${i}" ${i===state.station&&!showResult?'aria-current="step"':''}><span class="num">${done?'✓':String(i+1).padStart(2,'0')}</span>${s.title}</button>`;}).join('');
 document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>start(+b.dataset.station));$('#progressText').textContent=`${count} / ${totalTasks} Spuren bearbeitet`;$('#score').textContent=`${stations.filter((s,i)=>s.tasks.every((_,j)=>state.results[`${i}-${j}`]?.correct)).length} / 12 Aktenstücke`;$('#progress').max=totalTasks;$('#progress').value=count;
}
function imageFigure(id,compact=false){const m=imageArchive[id];if(!m)return '';return `<figure class="image-figure ${compact?'compact':''}"><button class="image-open" data-image="${id}" aria-label="Bild vergrössern: ${esc(m.caption)}"><img src="${m.src}" alt="${esc(m.alt)}" loading="lazy" decoding="async"><span class="zoom-badge">Vergrössern +</span></button><figcaption><strong>${esc(m.caption)}</strong><span>${esc(m.scope)}</span><small>${esc(m.creator)} · <a href="${m.source}" target="_blank" rel="noopener">Quelle</a> · <a href="${m.licenseUrl}" target="_blank" rel="noopener">${esc(m.license)}</a></small></figcaption></figure>`;}
function bindImages(){document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const id=b.dataset.image,m=imageArchive[id];$('#pictureContent').innerHTML=`<img src="${m.src}" alt="${esc(m.alt)}"><h2>${esc(m.caption)}</h2><p>${esc(m.scope)}</p><p class="small">${esc(m.creator)} · <a href="${m.source}" target="_blank" rel="noopener">Original & Bildnachweis</a> · <a href="${m.licenseUrl}" target="_blank" rel="noopener">${esc(m.license)}</a></p>`;$('#picture').showModal();});}
function render(){sidebar();if(showResult){renderResult();return;}const s=currentStation(),t=current();
 const labels={dig:'GRABUNGSFELD',text:'REGISTER ENTSCHLÜSSELN',write:'AKTENNOTIZ',number:'ZEITANKER',pairs:'PAARE VERBINDEN',sort:'KARTEN SORTIEREN',mark:'TEXT MARKIEREN',letters:'BUCHSTABENRÄTSEL',order:'REIHENFOLGE'};
 const primary=s.images?.[0],remaining=s.images?.slice(1)||[];
 $('#game').innerHTML=`<section class="station-lead"><div class="mission"><div class="eyebrow">AKTE ${String(state.station+1).padStart(2,'0')} / ${stations.length} · ${s.tag}</div><h2>${s.title}</h2><p>${s.intro}</p><div class="mission-links"><a href="#taskArea">An die Arbeit ↓</a><a href="#knowledge">Archiv konsultieren ↓</a></div></div>${primary?imageFigure(primary,true):''}</section>
 ${s.video?`<section class="video-panel"><div class="video-actions"><a href="${SRF}" target="_blank" rel="noopener">SRF-Beitrag ansehen ↗</a><button id="loadVideo" class="quiet">Video hier laden</button></div><p>Film: ca. 12 Minuten. Für die Aufgaben: 04:01–04:40, 07:09–07:39 und 10:31–11:21. Der Film führt nach Bern; er dient als Vergleich zur Neuchâtel-Reise.</p><p class="video-note">Erst beim Laden wird eine Verbindung zu SRF hergestellt. Alle benötigten Inhalte stehen auch im Expeditionswissen.</p><div id="video"></div></section>`:''}
 <section id="knowledge" class="knowledge"><div class="section-heading"><span class="eyebrow">NUR WENN IHR EINE SPUR BRAUCHT</span><h3>Das Archiv</h3></div><div class="knowledge-grid">${s.knowledge.map(k=>`<details class="knowledge-card"><summary>${k.title}</summary><p>${k.text}</p></details>`).join('')}</div><p class="source-line">${s.source}</p></section>
 ${remaining.length?`<section class="visual-evidence"><div class="section-heading"><span class="eyebrow">GENAU HINSEHEN</span><h3>Bildspuren</h3></div>${s.imageNote?`<p class="small">${s.imageNote}</p>`:''}<div class="gallery">${remaining.map(id=>imageFigure(id)).join('')}</div></section>`:''}
 <div id="taskArea" class="pills" aria-label="Aufgabe wählen">${s.tasks.map((_,i)=>`<button class="pill ${i===state.task?'active':''} ${state.results[`${state.station}-${i}`]?.correct?'done':''}" data-task="${i}" ${i===state.task?'aria-current="step"':''}>${i+1}. Spur</button>`).join('')}</div><section class="card"><div class="taskmeta">${labels[t.type]} · SPUR ${stations.slice(0,state.station).reduce((n,s)=>n+s.tasks.length,0)+state.task+1} / ${totalTasks}</div><h3>${t.q}</h3><div id="input"></div><div id="feedback" aria-live="polite"></div><div class="actions"><button id="check" class="primary">${t.type==='write'?'Notiz gegenlesen':t.type==='dig'?'Fundprotokoll sichern':'Spur prüfen'}</button><button id="next" class="quiet" ${state.results[key()]?.correct?'':'hidden'}>${state.task===s.tasks.length-1&&state.station===stations.length-1?'Akte zusammenführen':'Nächste Spur →'}</button></div><details><summary>Archiv dieser Akte öffnen</summary>${s.knowledge.map(k=>`<p><strong>${k.title}.</strong> ${k.text}</p>`).join('')}<p class="source-line">${s.source}</p></details></section>${!storageOK?'<p class="storage-warning">Dein Browser erlaubt kein Speichern. Dein Fortschritt bleibt nur für diese Sitzung erhalten.</p>':''}`;
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{start(state.station,+b.dataset.task);$('#taskArea').scrollIntoView({block:'start'});});if(s.video)$('#loadVideo').onclick=()=>{$('#video').innerHTML='<iframe title="SRF: Die Kelten und die Römer" src="https://www.srf.ch/play/embed?urn=urn:srf:video:3da18acb-1a0a-4cab-97ce-0b0fb3f4f4e4" allow="fullscreen" allowfullscreen></iframe>';$('#loadVideo').disabled=true;};
 const area=$('#taskArea'),card=area.nextElementSibling;const lead=$('.station-lead');lead.after(area,card);const archive=$('#knowledge');const wrapper=document.createElement('details');wrapper.className='archive-drawer';wrapper.innerHTML='<summary>Archiv öffnen · Hintergründe, Bilder und Quellen</summary>';archive.before(wrapper);wrapper.append(archive);const gallery=$('.visual-evidence');if(gallery)wrapper.append(gallery);document.querySelectorAll('a[href="#knowledge"]').forEach(a=>a.onclick=()=>{wrapper.open=true;});renderInput();$('#check').onclick=check;$('#next').onclick=next;bindImages();showReward();
}
function changed(){remember();$('#feedback').innerHTML='';$('#check').disabled=false;if(['write','dig'].includes(current().type)&&state.results[key()]?.correct){delete state.results[key()];save();sidebar();showReward();$('#next').hidden=true;document.querySelector(`[data-task="${state.task}"]`).classList.remove('done');}}
function renderInput(){const t=current(),el=$('#input');
 if(t.type==='dig'){renderDig(el,t);return;}
 if(['text','number','write'].includes(t.type)){const fields=t.fields||t.prompts?.map(label=>({label}))||[{label:t.label}];el.innerHTML=fields.map((f,i)=>`<label class="entry-label" for="entry-${i}">${f.label}</label>${t.type==='write'?`<textarea id="entry-${i}" data-entry="${i}" placeholder="Kurze Notiz ins Feldheft …">${esc(selection[i]||'')}</textarea>`:`<input id="entry-${i}" class="entry" data-entry="${i}" type="${t.type==='number'?'number':'text'}" ${t.type==='number'?'min="1" max="3000" step="1"':''} autocomplete="off" value="${esc(selection[i]??'')}">`}`).join('')+(t.type==='write'?'<p class="small">Stichhaltige Notizen reichen. Beim Gegenlesen entscheidest du selbst, ob deine Aussage von den Spuren getragen wird.</p>':'');document.querySelectorAll('[data-entry]').forEach(b=>b.oninput=()=>{selection[+b.dataset.entry]=b.value;changed();});}
 else if(t.type==='order'){el.innerHTML=`<p class="small">${t.instruction||'Verschiebe mit den Pfeil-Schaltflächen. Oben steht das älteste Ereignis.'}</p>`+order.map((id,pos)=>`<div class="order-row"><span>${pos+1}</span><span class="rowtext">${t.items[id]}</span><div class="move"><button data-move="${pos}" data-dir="-1" ${pos===0?'disabled':''} aria-label="${esc(t.items[id])} nach oben">↑</button><button data-move="${pos}" data-dir="1" ${pos===order.length-1?'disabled':''} aria-label="${esc(t.items[id])} nach unten">↓</button></div></div>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.dir);[order[i],order[j]]=[order[j],order[i]];changed();renderInput();document.querySelector(`[data-move="${j}"]:not(:disabled)`)?.focus();});}
 else if(t.type==='mark'){el.innerHTML='<p class="small">Markiere einzelne Wörter per Klick oder Tastatur. Erneutes Anklicken entfernt die Markierung.</p><div class="passage">'+t.passage.map((w,i)=>`<button class="word ${selection.includes(i)?'marked':''}" data-word="${i}" aria-pressed="${selection.includes(i)}">${w}</button>`).join(' ')+'</div>';document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const i=+b.dataset.word;selection=selection.includes(i)?selection.filter(v=>v!==i):[...selection,i];changed();renderInput();document.querySelector(`[data-word="${i}"]`).focus();});}
 else if(t.type==='letters'){el.innerHTML='<p class="small">Setze die Buchstaben zum gesuchten Wort zusammen. Klicke oben auf einen Buchstaben, um ihn zurückzulegen.</p><div class="letter-slots" aria-label="Dein Lösungswort">'+selection.map((id,i)=>`<button class="letter filled" data-remove="${i}" aria-label="${t.letters[id]} zurücklegen">${t.letters[id]}</button>`).join('')+Array.from({length:t.letters.length-selection.length},()=>'<span class="letter empty">·</span>').join('')+'</div><div class="letter-bank">'+t.letters.map((l,i)=>`<button class="letter" data-letter="${i}" ${selection.includes(i)?'disabled':''} aria-label="${l} einsetzen">${l}</button>`).join('')+'</div>';document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{selection.push(+b.dataset.letter);changed();renderInput();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selection.splice(+b.dataset.remove,1);changed();renderInput();});}
 else if(t.type==='sort'||t.type==='pairs'){el.innerHTML=`<p class="small">${t.type==='pairs'?'Wähle links einen Begriff und rechts seine Verbindung. Jede rechte Karte gehört zu genau einem Begriff.':'Wähle eine Fundkarte und lege sie per Klick in die passende Kategorie. Du kannst Karten jederzeit neu zuordnen.'}</p><div class="connections"><div class="card-bank">${t.items.map((item,i)=>`<button class="connect-card ${activeCard===i?'selected':''}" data-card="${i}" aria-pressed="${activeCard===i}"><strong>${i+1}. ${item}</strong>${Number.isInteger(selection[i])?`<small>→ ${t.categories[selection[i]]}</small>`:'<small>Noch nicht zugeordnet</small>'}</button>`).join('')}</div><div class="targets">${t.categories.map((c,j)=>`<button class="connect-target" data-target="${j}" ${activeCard===null?'disabled':''}><strong>${c}</strong><small>${t.items.map((_,i)=>selection[i]===j?String(i+1):'').filter(Boolean).join(', ')||'—'}</small></button>`).join('')}</div></div><p class="small" role="status">${activeCard===null?'Wähle zuerst eine Karte.':`Karte ${activeCard+1} gewählt. Wähle jetzt das Ziel.`}</p>`;document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{activeCard=+b.dataset.card;renderInput();document.querySelector('[data-target]')?.focus();});document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const j=+b.dataset.target;if(t.type==='pairs')selection=selection.map(v=>v===j?null:v);selection[activeCard]=j;activeCard=null;changed();renderInput();});}
}
function complete(correct,self=false){const prev=state.results[key()];state.results[key()]={first:self?false:prev?prev.first:correct,correct:!!prev?.correct||correct};save();sidebar();showReward();$('#next').hidden=!state.results[key()].correct;document.querySelector(`[data-task="${state.task}"]`)?.classList.toggle('done',state.results[key()].correct);}
function check(){const t=current();let valid=true,correct=false;
 if(t.type==='dig'){const done=t.finds.every((f,i)=>selection[i]==='recorded');if(done){complete(true,true);$('#feedback').innerHTML='<div class="feedback"><strong>Fundkontext gesichert.</strong><p>'+t.why+'</p></div>';$('#check').disabled=true;}else $('#feedback').innerHTML='<p>Legt erst alle drei Funde frei, zeichnet ihre Lage ein und sichert sie dann.</p>';return;}
 if(t.type==='write'){valid=t.prompts.every((_,i)=>String(selection[i]||'').trim().length>=12);if(valid){$('#feedback').innerHTML=`<div class="feedback"><strong>Hält eure Notiz den Spuren stand?</strong><p>${t.why}</p><div class="rubric">${t.criteria.map((c,i)=>`<label><input type="checkbox" data-criterion="${i}">${c}</label>`).join('')}</div><p class="small">Bestätige nur Kriterien, die dein Text tatsächlich erfüllt. Du kannst ihn oben weiterbearbeiten.</p><button class="primary" id="selfDone" disabled>Notiz in die Akte legen</button></div>`;document.querySelectorAll('[data-criterion]').forEach(b=>b.onchange=()=>{$('#selfDone').disabled=![...document.querySelectorAll('[data-criterion]')].every(c=>c.checked);});$('#selfDone').onclick=()=>{complete(true,true);$('#selfDone').disabled=true;$('#selfDone').textContent='Notiz abgelegt';};return;}}
 else if(t.type==='text'){valid=t.fields.every((_,i)=>String(selection[i]||'').trim());correct=t.fields.every((f,i)=>f.accept.some(a=>normalize(a)===normalize(selection[i]||'')));}
 else if(t.type==='number'){valid=String(selection[0]||'').trim()!=='';correct=Number(selection[0])===t.answer;}
 else if(t.type==='letters'){valid=selection.length===t.letters.length;correct=selection.map(i=>t.letters[i]).join('')===t.answer;}
 else if(t.type==='order'){correct=JSON.stringify(order)===JSON.stringify(t.answer);}
 else if(t.type==='mark'){valid=selection.length>0;correct=JSON.stringify([...selection].sort((a,b)=>a-b))===JSON.stringify(t.answer);}
 else{valid=t.items.every((_,i)=>Number.isInteger(selection[i]));correct=JSON.stringify(selection)===JSON.stringify(t.answer);}
 if(!valid){$('#feedback').innerHTML=`<p role="status">${t.type==='write'?'Bitte formuliere zu jedem Feld einen kurzen Gedanken (mindestens 12 Zeichen). Das ist nur eine Eingabeprüfung, keine Bewertung.':'Bitte vervollständige zuerst deine Lösung.'}</p>`;return;}
 complete(correct);$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'Spur entschlüsselt!':'Noch nicht ganz.'}</strong><p>${t.why}</p>${!correct&&t.type==='text'?`<p>Gesuchte Begriffe: ${t.fields.map(f=>f.accept[0]).join(' · ')}</p>`:''}${correct?'':'<p>Überarbeite deine Lösung mit diesem Hinweis und prüfe sie erneut.</p>'}</div>`;$('#check').disabled=true;
}
function next(){if(state.task<currentStation().tasks.length-1){start(state.station,state.task+1);$('#taskArea').scrollIntoView({block:'start'});}else if(state.station<stations.length-1)start(state.station+1);else{showResult=true;render();$('#game').focus();}}
function renderResult(){const points=Object.values(state.results).filter(r=>r.first).length,solved=Object.values(state.results).filter(r=>r.correct).length;
 const missing=stations.flatMap((s,i)=>s.tasks.map((t,j)=>({s:i,t:j,title:s.title,result:state.results[`${i}-${j}`]}))).filter(x=>!x.result?.correct);
 $('#game').innerHTML=`<section class="mission"><div class="eyebrow">EUREFUND AKTE</div><h2>${solved===totalTasks?'Die Akte ist vollständig.':'Es gibt noch Spuren zu entdecken.'}</h2><div class="result-number">${solved}<span style="font-size:26px"> / ${totalTasks}</span></div><p>Eure Funde, Registereinträge und gegengelesenen Notizen sind in der Akte gesammelt. ${solved===totalTasks?'Du hast alle Aufgaben abgeschlossen. Verteidigt jetzt eure Erklärung.':'Kehre zu den offenen Aufgaben zurück.'}</p></section>${missing.length?`<div class="review-list">${missing.map(x=>`<button class="quiet" data-review="${x.s},${x.t}">${x.title} · Spur ${x.t+1} bearbeiten →</button>`).join('')}</div>`:''}<section class="card final-card"><div class="taskmeta">DIE SCHLUSSDEUTUNG</div><h3>La Tène – Unter der Oberfläche</h3><p>Was verraten die Spuren von La Tène, und welche Geschichten entstehen erst durch ihre Deutung? Verbinde einen Fund oder den Fundort mit einem Text und einem späteren Bild. Benenne eine Grenze dieser Verbindungen.</p><label for="judgment" class="small">Eure Erklärung · wird nur lokal gespeichert</label><textarea id="judgment" placeholder="Von La Tène aus haben wir entdeckt …">${esc(state.draft)}</textarea><details class="rubric"><summary>Selbstcheck und Beispiel</summary><p>Dein Text wird nicht automatisch benotet. Prüfe ihn anhand dieser Kriterien:</p><label><input type="checkbox">Ich nenne mindestens zwei konkrete Belege.</label><label><input type="checkbox">Ich unterscheide Funde, Deutungen und fremde Perspektiven.</label><label><input type="checkbox">Ich unterscheide Helvetier, andere keltische Gruppen und die heutige Schweiz.</label><p><strong>Mögliche Antwort:</strong> Die Funde von La Tène geben Einblicke in die keltische Welt, doch ein Objekt allein verrät nicht sicher die Zugehörigkeit seiner Benutzer. Über den Auszug der Helvetier berichtet mit Caesar ein beteiligter Gegner. Helvetia verkörpert die Schweiz in späteren Bildern und ist keine antike Person. Fund, Bericht und Allegorie erzählen auf unterschiedliche Weise Geschichte; ihre Verbindungen müssen jeweils begründet werden.</p></details><details><summary>Weiterdenken: Was erzählt der Name Helvetia?</summary><p>Die Präsentation zeigt, wie Asterix unser Keltenbild prägen kann. Vergleiche damit den Bezug auf die Helvetier im Namen Helvetia: Welche Bilder von Vergangenheit und Zugehörigkeit entstehen?</p><p>Welche anderen antiken Gruppen geraten aus dem Blick, wenn man die Helvetier als Stellvertreter der gesamten heutigen Schweiz verwendet? Berücksichtige etwa Rauriker oder Lepontier.</p></details><div class="actions"><button class="primary" id="download">Bericht herunterladen</button><button class="quiet" id="print">Drucken</button><button class="quiet" id="again">Stationen wiederholen</button></div></section>`;
 const dossier=document.createElement('section');dossier.className='case-reward';dossier.innerHTML='<h3>Eure Beweiskette</h3><p>'+esc(board.hypothesis||state.answers['0-2']?.[0]||'Tragt eure Vermutung in die Fundakte ein.')+'</p><ul>'+stations.map((s,i)=>caseDone(i)&&board.links[i]?'<li>'+esc(s.reward.title)+' — '+({supports:'stützt eure Vermutung',challenges:'begrenzt eure Vermutung',open:'öffnet eine Frage'}[board.links[i]])+'</li>':'').join('')+'</ul><button class="quiet" id="resultBoard">Belege verbinden →</button>';$('.final-card').before(dossier);$('#resultBoard').onclick=openBoard;$('#judgment').oninput=e=>{state.draft=e.target.value;save();};$('#print').onclick=()=>window.print();$('#again').onclick=()=>start(0);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>start(...b.dataset.review.split(',').map(Number)));
 $('#download').onclick=()=>{const report=`LA TÈNE – UNTER DER OBERFLÄCHE · SPURENBERICHT\n\nAbgeschlossen: ${solved}/${totalTasks}\n${stations.map((s,i)=>s.title+': '+s.tasks.filter((_,j)=>state.results[`${i}-${j}`]?.correct).length+'/3 gelöst').join('\n')}\n\nMEINE AUFGABENTEXTE\n${stations.flatMap((s,i)=>s.tasks.map((t,j)=>s.title+' – '+t.q+'\n'+(t.type==='write'?t.prompts.map((p,n)=>p+': '+(state.answers[`${i}-${j}`]?.[n]||'(offen)')).join('\n'):formatAnswer(t,state.answers[`${i}-${j}`]||[])))).filter(Boolean).join('\n\n')}\n\nUNSERE SCHLUSSDEUTUNG\n${state.draft||'(Noch kein Text verfasst.)'}\n\nGrundlagen: Informationen zu den Helvetiern.pdf; Die Kelten.docx; PPP_Kelten (1).pptx; SRF: Die Kelten und die Römer.\n${SRF}`;const url=URL.createObjectURL(new Blob([report+boardReport()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='La-Tene-Spurenbericht.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
function formatAnswer(t,a){if(t.type==='dig')return t.finds.map((f,i)=>f.name+': '+(a[i]==='recorded'?'Lage dokumentiert und gesichert':'noch offen')).join('; ');if(!a.length)return '(offen)';if(t.type==='order')return a.map((id,i)=>`${i+1}. ${t.items[id]}`).join(' → ');if(t.type==='pairs'||t.type==='sort')return t.items.map((v,i)=>`${v}: ${t.categories[a[i]]||'(offen)'}`).join('; ');if(t.type==='mark')return a.map(i=>t.passage[i]).join(' ');if(t.type==='letters')return a.map(i=>t.letters[i]).join('');return a.join(' · ');}
